import{_ as a,o,c as n,a3 as t}from"./chunks/framework.CchDE9cb.js";const m=JSON.parse('{"title":"Glossary","description":"The plain-language meaning of every term these docs use, from account to user.","frontmatter":{"title":"Glossary","description":"The plain-language meaning of every term these docs use, from account to user."},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":null}'),i={name:"reference/glossary.md"};function s(r,e,l,c,h,d){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Every jargon word in these docs links here the first time it appears. This page is the full list, in plain language, with a link to where each term is covered in depth.</p><h2 id="account" tabindex="-1">account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;account&quot;">​</a></h2><p>An account is CapacityLens&#39;s internal name for a company workspace — the isolated set of clients, projects, people and schedule data one team works in. Day-to-day, these docs call it a company: an installation can host one company, or several once multi-company is turned on, each fully separated on every request. One screen uses the word in its everyday sense instead: the first-run &quot;Create the owner account&quot; form, where it means the Owner&#39;s own sign-in. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p><h2 id="activity" tabindex="-1">activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;activity&quot;">​</a></h2><p>An activity is the specific thing a person is booked to do on an allocation — project-specific, internal (not tied to a project), or cross-project, like general account management. See <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a>.</p><h2 id="admin" tabindex="-1">admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;admin&quot;">​</a></h2><p>Admin is the second-highest of the four roles a member can hold in a company, below Owner and above Editor and Viewer. An Admin can invite and manage other members, see time-off notes, and restore or purge archived data — but cannot touch the Owner or transfer ownership. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p><h2 id="allocation" tabindex="-1">allocation <a class="header-anchor" href="#allocation" aria-label="Permalink to &quot;allocation&quot;">​</a></h2><p>An allocation is a block of work placed on the schedule for a person: a project, a date range, and a status of tentative, confirmed or completed. Dragging out three days of a designer&#39;s time on a project is one allocation. See <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a>.</p><h2 id="break-glass" tabindex="-1">break-glass <a class="header-anchor" href="#break-glass" aria-label="Permalink to &quot;break-glass&quot;">​</a></h2><p>Break-glass is the fast, deliberate rollback from single sign-on back to mixed mode (passwords and company login both) if something goes wrong after cutover: change two settings back and restart. Passwords are kept, not deleted, during an SSO-only cutover for exactly this reason. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="claims" tabindex="-1">claims <a class="header-anchor" href="#claims" aria-label="Permalink to &quot;claims&quot;">​</a></h2><p>Claims are the facts an identity provider reports about a person during company login — their email address, whether that email is verified, and a stable ID that doesn&#39;t change. CapacityLens relies on these to admit someone and keep their sign-in linked to the same person. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="client-secret" tabindex="-1">client secret <a class="header-anchor" href="#client-secret" aria-label="Permalink to &quot;client secret&quot;">​</a></h2><p>A client secret is the private, random string an identity provider issues alongside a client ID, proving that sign-in requests really come from your CapacityLens server. It&#39;s usually shown once and should be treated like a root password. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="company-login" tabindex="-1">company login <a class="header-anchor" href="#company-login" aria-label="Permalink to &quot;company login&quot;">​</a></h2><p>Company login is the everyday name for signing in through the identity provider your organisation already uses for email — Google Workspace, Microsoft Entra, Okta or similar — instead of a CapacityLens-specific password. See <a href="/capacitylens/company-login/">How sign-in works</a>.</p><h2 id="cutover" tabindex="-1">cutover <a class="header-anchor" href="#cutover" aria-label="Permalink to &quot;cutover&quot;">​</a></h2><p>Cutover is the moment a self-hosted installation switches from mixed mode to company-login only, closing the password door for good. It happens once every active member is connected and the readiness check passes. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="demo-mode" tabindex="-1">demo mode <a class="header-anchor" href="#demo-mode" aria-label="Permalink to &quot;demo mode&quot;">​</a></h2><p>Demo mode is the in-memory, nothing-to-install version of CapacityLens: a fictional two-company sample dataset that resets on every reload and has no real logins, memberships or roles. It&#39;s what <a href="/capacitylens/getting-started/try-the-demo">Try the demo</a> runs.</p><h2 id="discipline" tabindex="-1">discipline <a class="header-anchor" href="#discipline" aria-label="Permalink to &quot;discipline&quot;">​</a></h2><p>A discipline is a category people are grouped by across the app — Design, Development, and so on — used for filtering and for per-discipline utilisation figures. Turned on by default. See <a href="/capacitylens/guide/settings">Settings</a>.</p><h2 id="external-party" tabindex="-1">external party <a class="header-anchor" href="#external-party" aria-label="Permalink to &quot;external party&quot;">​</a></h2><p>An external party is a non-capacity-tracked resource on the schedule, such as a print shop or a subcontractor, that can be booked without counting toward anyone&#39;s utilisation. Off by default. See <a href="/capacitylens/guide/settings">Settings</a>.</p><h2 id="identity-provider" tabindex="-1">identity provider <a class="header-anchor" href="#identity-provider" aria-label="Permalink to &quot;identity provider&quot;">​</a></h2><p>An identity provider (IdP) is the outside system that checks a person&#39;s password or company login and tells CapacityLens who they are — Google, Microsoft Entra, Okta or Keycloak, for example. These docs use the everyday name, company login, wherever possible; see <a href="/capacitylens/company-login/">How sign-in works</a>.</p><h2 id="invite" tabindex="-1">invite <a class="header-anchor" href="#invite" aria-label="Permalink to &quot;invite&quot;">​</a></h2><p>An invite is a single-use link an Owner or Admin creates for a specific role, and optionally a specific email address, so someone can join a company. CapacityLens shows the link once and never emails it — the person who creates it has to send it themselves. See <a href="/capacitylens/getting-started/invite-your-team">Invite your team</a>.</p><h2 id="issuer" tabindex="-1">issuer <a class="header-anchor" href="#issuer" aria-label="Permalink to &quot;issuer&quot;">​</a></h2><p>The issuer is the exact web address an identity provider uses to identify itself in its discovery document. CapacityLens compares it character for character against the address you configure, and refuses to start if they don&#39;t match. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="link-accounts" tabindex="-1">link (accounts) <a class="header-anchor" href="#link-accounts" aria-label="Permalink to &quot;link (accounts)&quot;">​</a></h2><p>Linking is the step where a signed-in person connects their password identity to their company login provider, proving the two are the same person before single sign-on can take over. Linking keeps the person&#39;s existing membership, role and scheduling history untouched. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="member" tabindex="-1">member <a class="header-anchor" href="#member" aria-label="Permalink to &quot;member&quot;">​</a></h2><p>A member is a person&#39;s membership in one company: an identity, a role and a status, scoped to that company alone. Being a member doesn&#39;t automatically put someone on the schedule, and being on the schedule doesn&#39;t automatically make someone a member — CapacityLens keeps these as deliberately separate records. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p><h2 id="mfa-totp" tabindex="-1">MFA / TOTP <a class="header-anchor" href="#mfa-totp" aria-label="Permalink to &quot;MFA / TOTP&quot;">​</a></h2><p>MFA (multi-factor authentication) is a second proof of identity beyond a password. TOTP (time-based one-time password) is the six-digit authenticator-app code CapacityLens uses for it. An operator can require MFA for every password sign-in with one setting. See <a href="/capacitylens/security/">Security overview</a>.</p><h2 id="mixed-mode" tabindex="-1">mixed mode <a class="header-anchor" href="#mixed-mode" aria-label="Permalink to &quot;mixed mode&quot;">​</a></h2><p>Mixed mode is the deployment setting where password sign-in and company login are both switched on at once, so people can connect their company login account before the password door closes. It&#39;s a supported way to run CapacityLens permanently, not just a migration stage. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="oidc" tabindex="-1">OIDC <a class="header-anchor" href="#oidc" aria-label="Permalink to &quot;OIDC&quot;">​</a></h2><p>OIDC (OpenID Connect) is the technical standard CapacityLens&#39;s single sign-on is built on — the jargon behind the everyday phrase company login. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="owner" tabindex="-1">owner <a class="header-anchor" href="#owner" aria-label="Permalink to &quot;owner&quot;">​</a></h2><p>The Owner is the one person per company with full control: the only role that can delete the company, replace its whole dataset, or transfer ownership. Every company has exactly one Owner, and no Admin can reset an Owner&#39;s password or remove them. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p><h2 id="password-mode" tabindex="-1">password mode <a class="header-anchor" href="#password-mode" aria-label="Permalink to &quot;password mode&quot;">​</a></h2><p>Password mode is the setting where people sign in with an email and password stored by CapacityLens itself, rather than through a company login provider. It&#39;s the default for a new self-hosted install. See <a href="/capacitylens/self-hosting/configuration">Configuration</a>.</p><h2 id="person" tabindex="-1">person <a class="header-anchor" href="#person" aria-label="Permalink to &quot;person&quot;">​</a></h2><p>A person is a schedulable resource — someone who can receive allocations and time off on the schedule. A person doesn&#39;t need a CapacityLens login: you can schedule a freelancer, or a role you haven&#39;t hired yet, without ever inviting them as a member. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</p><h2 id="pkce" tabindex="-1">PKCE <a class="header-anchor" href="#pkce" aria-label="Permalink to &quot;PKCE&quot;">​</a></h2><p>PKCE is an extra check built into the sign-in handshake that stops a stolen sign-in code being reused by someone else. CapacityLens requires it from every identity provider it connects to. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="placeholder" tabindex="-1">placeholder <a class="header-anchor" href="#placeholder" aria-label="Permalink to &quot;placeholder&quot;">​</a></h2><p>A placeholder is an unfilled slot you pencil into the schedule before a role is hired or assigned — a way to plan for work you know is coming without naming a real person yet. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</p><h2 id="readiness" tabindex="-1">readiness <a class="header-anchor" href="#readiness" aria-label="Permalink to &quot;readiness&quot;">​</a></h2><p>Readiness is what the SSO cutover readiness panel in Team &amp; access reports: whether every active member of a company has connected their company login account, so cutover can happen without locking anyone out. The same check runs as a command an operator can run before cutover. See <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="redirect-uri" tabindex="-1">redirect URI <a class="header-anchor" href="#redirect-uri" aria-label="Permalink to &quot;redirect URI&quot;">​</a></h2><p>A redirect URI (also called a callback URL) is the exact web address your identity provider sends someone back to once they&#39;ve signed in. It has to match your CapacityLens address character for character, or the first sign-in click fails. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>.</p><h2 id="role" tabindex="-1">role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;role&quot;">​</a></h2><p>A role is what a member is allowed to do in a company: Viewer, Editor, Admin or Owner, each able to do everything the role below it can plus more. Roles are set per company, so the same person can be an Editor in one company and a Viewer in another. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</p><h2 id="schedule" tabindex="-1">schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;schedule&quot;">​</a></h2><p>The schedule is the single week-by-week grid at the centre of CapacityLens, showing every person&#39;s allocations and time off, zoomable from one to eight weeks. See <a href="/capacitylens/guide/the-schedule">The schedule</a>.</p><h2 id="session" tabindex="-1">session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;session&quot;">​</a></h2><p>A session is the period between signing in and signing out, or timing out, tracked by CapacityLens on the server. A session lasts at most twelve hours and ends after thirty minutes of inactivity, whichever comes first. See <a href="/capacitylens/security/">Security overview</a>.</p><h2 id="single-sign-on-sso" tabindex="-1">single sign-on (SSO) <a class="header-anchor" href="#single-sign-on-sso" aria-label="Permalink to &quot;single sign-on (SSO)&quot;">​</a></h2><p>Single sign-on (SSO) lets people sign in to CapacityLens with the same account they use for the rest of their company&#39;s tools, instead of a separate password. It&#39;s the formal name for what these docs call company login. See <a href="/capacitylens/company-login/">How sign-in works</a>.</p><h2 id="snapshot-offline" tabindex="-1">snapshot (offline) <a class="header-anchor" href="#snapshot-offline" aria-label="Permalink to &quot;snapshot (offline)&quot;">​</a></h2><p>A snapshot is the read-only copy of a company&#39;s schedule CapacityLens stores on your device when offline access is turned on, so you can check it without a connection. Snapshots expire after seven days and never accept edits. See <a href="/capacitylens/guide/offline-access">Offline access</a>.</p><h2 id="social-sign-in" tabindex="-1">social sign-in <a class="header-anchor" href="#social-sign-in" aria-label="Permalink to &quot;social sign-in&quot;">​</a></h2><p>Social sign-in is the experimental &quot;Continue with Google/Microsoft/GitHub&quot; button, separate from company login. After a company has moved to single sign-on, a social button can let an existing person sign in, but it can&#39;t create a new one. See <a href="/capacitylens/company-login/">How sign-in works</a>.</p><h2 id="sqlite-the-database" tabindex="-1">SQLite / the database <a class="header-anchor" href="#sqlite-the-database" aria-label="Permalink to &quot;SQLite / the database&quot;">​</a></h2><p>SQLite is the single-file database CapacityLens stores everything in — every company, person, allocation and audit entry. Self-hosting keeps that one file, plus its backups, on persistent storage. See <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a>.</p><h2 id="time-off" tabindex="-1">time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;time off&quot;">​</a></h2><p>Time off is a block on the schedule marking a person unavailable — holiday, sick leave or unpaid leave — drawn onto the same canvas as their work so capacity stays honest. See <a href="/capacitylens/guide/time-off">Time off</a>.</p><h2 id="user" tabindex="-1">user <a class="header-anchor" href="#user" aria-label="Permalink to &quot;user&quot;">​</a></h2><p>A user is a login identity: the record that lets someone sign in at all, scoped to the whole installation rather than to one company. One user can be a member of several companies, each with a different role — and a user existing doesn&#39;t put anyone on the schedule; a person and a member are separate records for that. See <a href="/capacitylens/getting-started/invite-your-team">Invite your team</a>.</p><h2 id="utilisation" tabindex="-1">utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;utilisation&quot;">​</a></h2><p>Utilisation is how much of a person&#39;s available time is booked with allocations, shown as a percentage. CapacityLens can show total, per-discipline and personal utilisation figures, and some scheduling modes let work be booked without counting toward it. See <a href="/capacitylens/guide/settings">Settings</a>.</p>',76)])])}const u=a(i,[["render",s]]);export{m as __pageData,u as default};
